/* @lc app=leetcode id=2289 lang=kotlin */
class Solution { fun totalSteps(nums: IntArray): Int = nums.indices.fold(0 to mutableListOf<Pair<Int, Int>>()) { (r, s), i -> (if (s.isEmpty()) 0 else (generateSequence { s.takeIf { it.isNotEmpty() && nums[it.last().first] <= nums[i] }?.removeAt(s.size - 1)?.second }.maxOrNull() ?: 0).let { if (s.isEmpty()) 0 else it + 1 }).let { st -> maxOf(r, st) to s.apply { add(i to st) } } }.first }